+    <video src={backgroundMovie} class="absolute inset-0 w-full h-full object-cover object-center backdrop-blur-3xl" crossorigin="anonymous" autoplay playsinline preload="auto" muted loop tabindex="-1" />
+    <section
+      class="flex w-full h-full justify-center items-start m-auto p-auto lg:flex-row flex-col gap-16 z-10"
