+      {
+        sectionsMapped.map((section) => (
+          <div
+            class="flex justify-center align-middle lg:m-0 m-auto border-2 border-white rounded-2xl hover:scale-90 transition duration-850"
+            aria-label={section.name}
+          >
+            <form action={section.href} method="post">
+              <button
+                type="submit"
+                class="w-[28rem] h-[8rem] scale-90 hover:drop-shadow-2xl"
+              >
+                <img
+                  class="w-full h-full object-contain"
+                  src={section.image.filename}
+                  alt={section.name}
+                />
+                {/* <span>{section.name}</span> */}
+              </button>
+            </form>
+          </div>
+        ))
+      }
+    </section>
+  </main>
+</ContextLayout>

